result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_enrich.py", "content": "import pandas as pd
import pytest

from enrich import enrich_orders


def make_orders() -> pd.DataFrame:
    return pd.DataFrame(
        {
            "order_id": [1, 2, 3, 4],
            "customer_id": [10, 11, 12, 13],
        }
    )


def test_duplicate_customer_rows_do_not_fan_out_orders():
    """Regression: duplicated customer_id in customers used to silently
    fan out orders during the merge."""
    orders = make_orders()
    customers = pd.DataFrame(
        {
            "customer_id": [10, 10, 11],
            "email": ["a@x.com", "newer@x.com", "b@x.com"],
            "updated_at": ["2026-01-01", "2026-06-01", "2026-02-01"],
        }
    )

    result = enrich_orders(orders, customers)

    assert len(result) == len(orders) == 4
    # The surviving row for customer 10 must be the one with the latest updated_at
    assert result.loc[result["customer_id"] == 10, "email"].item() == "newer@x.com"
    # Orders whose customer is missing get the 'unknown' placeholder
    assert result.loc[result["customer_id"] == 13, "email"].item() == "unknown"


def test_updated_at_ties_are_unresolvable_and_raise():
    orders = make_orders()
    customers = pd.DataFrame(
        {
            "customer_id": [10, 10],
            "email": ["a@x.com", "b@x.com"],
            "updated_at": ["2026-06-01", "2026-06-01"],  # tie: no unique latest
        }
    )

    with pytest.raises(ValueError):
        enrich_orders(orders, customers)


def test_no_duplicates_passthrough():
    orders = make_orders()
    customers = pd.DataFrame(
        {
            "customer_id": [10, 11, 12, 13, 14],
            "email": ["a@x.com", None, "c@x.com", "d@x.com", "e@x.com"],
            "updated_at": ["2026-01-01"] * 5,
        }
    )

    result = enrich_orders(orders, customers)

    assert len(result) == 4
    assert result["email"].isna().sum() == 0
"})
